function opponentLogo(name) {
  const key = OPPONENT_LOGO_MAP[name];
  return key ? OPPONENT_LOGOS[key] : null;
}
function teamLogo(name) {
  return name === "Amsterdam Mustangs" ? LOGO : opponentLogo(name);
}

